package com.tradechatfiller;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(TradeChatFillerConfig.GROUP)
public interface TradeChatFillerConfig extends Config
{
	String GROUP = "tradechatfiller";
	int MAX_MESSAGES = 20;

	@Range(
		min = 1,
		max = MAX_MESSAGES
	)
	@ConfigItem(
		keyName = "messageCount",
		name = "Message count",
		description = "How many times an incoming trade request is shown in the trade chat (1-20)",
		position = 0
	)
	default int messageCount()
	{
		return 8;
	}
}

package com.tradechatfiller;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Trade Chat Filler",
	description = "Fills the trade chat with incoming trade requests so they are easy to click",
	tags = {"trade", "chat", "runner", "running", "bones", "prayer", "runecrafting"}
)
public class TradeChatFillerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private TradeChatFillerConfig config;

	/**
	 * Set while we are re-adding a trade request, since addChatMessage fires
	 * another ChatMessage event that we must not duplicate again.
	 */
	private boolean filling;

	@Override
	protected void shutDown()
	{
		filling = false;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (filling || event.getType() != ChatMessageType.TRADEREQ)
		{
			return;
		}

		// The original request is already one of the lines shown
		int copies = Math.min(config.messageCount(), TradeChatFillerConfig.MAX_MESSAGES) - 1;
		if (copies <= 0)
		{
			return;
		}

		log.debug("Filling trade chat with {} copies of trade request from {}", copies, event.getName());

		filling = true;
		try
		{
			for (int i = 0; i < copies; i++)
			{
				client.addChatMessage(event.getType(), event.getName(), event.getMessage(), event.getSender());
			}
		}
		finally
		{
			filling = false;
		}
	}

	@Provides
	TradeChatFillerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TradeChatFillerConfig.class);
	}
}

package com.tradechatfiller;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TradeChatFillerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TradeChatFillerPlugin.class);
		RuneLite.main(args);
	}
}
